begin;
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000004101','shared-a@example.test'),('00000000-0000-4000-8000-000000004102','shared-b@example.test');
insert into businesses(id,name,slug) values ('00000000-0000-4000-8000-000000004101','Shared A','shared-a'),('00000000-0000-4000-8000-000000004102','Shared B','shared-b');
insert into business_users(business_id,user_id,role) values ('00000000-0000-4000-8000-000000004101','00000000-0000-4000-8000-000000004101','owner'),('00000000-0000-4000-8000-000000004102','00000000-0000-4000-8000-000000004102','owner');
insert into workflows(id,business_id,name) values('00000000-0000-4000-8000-000000004111','00000000-0000-4000-8000-000000004101','Original');
insert into workflow_steps(workflow_id,key,position,kind,config) values('00000000-0000-4000-8000-000000004111','customer',0,'customer','{"label":"Adresa"}');
insert into products(id,business_id,name,workflow_id) values('00000000-0000-4000-8000-000000004121','00000000-0000-4000-8000-000000004101','Product A','00000000-0000-4000-8000-000000004111'),('00000000-0000-4000-8000-000000004122','00000000-0000-4000-8000-000000004101','Product B','00000000-0000-4000-8000-000000004111');
set constraints all immediate;
do $$ declare a uuid:='00000000-0000-4000-8000-000000004101';b uuid:='00000000-0000-4000-8000-000000004102';p uuid:='00000000-0000-4000-8000-000000004121';wid uuid:='00000000-0000-4000-8000-000000004111';old_version uuid;new_wid uuid;expected jsonb;definition jsonb:='{"name":"New steps","steps":[{"key":"phone","kind":"text","fieldKey":"customer_phone","fieldType":"phone"},{"key":"customer","kind":"customer"}]}';
begin
 select id into old_version from linear_workflow_versions where workflow_id=wid order by created_at desc limit 1;
 expected:=jsonb_build_object('workflowId',wid,'versionId',old_version,'sourceVersionId',old_version,'affected',jsonb_build_array(p));
 if old_version is null then raise exception 'Legacy version missing'; end if;
 begin perform save_product_workflow(a,b,p,0,definition,'product','draft',null,expected);raise exception 'Cross tenant write accepted' using errcode='XX001';exception when raise_exception then if sqlerrm<>'unauthorized' then raise;end if;end;
 perform save_product_workflow(a,a,p,0,definition,'product','draft',null,expected);
 if (select workflow_id from products where id=p)<>wid or (select count(*) from workflow_steps where workflow_id=wid)<>1 then raise exception 'Draft changed active steps';end if;
 begin perform save_product_workflow(a,a,p,0,null,'product','publish',null,expected);raise exception 'Stale revision accepted' using errcode='XX001';exception when raise_exception then if sqlerrm<>'stale_workflow' then raise;end if;end;
 perform save_product_workflow(a,a,p,1,null,'product','publish',null,expected);
 select workflow_id into new_wid from products where id=p;
 if new_wid=wid then raise exception 'Shared workflow not copied';end if;
 if (select workflow_id from products where id='00000000-0000-4000-8000-000000004122')<>wid then raise exception 'Other product changed';end if;
 if (select steps from linear_workflow_versions where id=old_version)<> '[{"key":"customer","kind":"customer","label":"Adresa","required":true}]'::jsonb then raise exception 'Old version changed';end if;
 if not exists(select 1 from workflow_steps where workflow_id=new_wid and config->>'fieldKey'='customer_phone') then raise exception 'Field binding lost';end if;
 if has_table_privilege('authenticated','conversation_profiles','select') or has_table_privilege('service_role','linear_workflow_versions','update') or has_function_privilege('authenticated','save_product_workflow(uuid,uuid,uuid,integer,jsonb,text,text,uuid,jsonb)','execute') then raise exception 'Boundary exposed';end if;
end $$;
insert into instagram_connections(id,business_id,ig_user_id,access_token_ciphertext) values('00000000-0000-4000-8000-000000004131','00000000-0000-4000-8000-000000004101','test-shared-account','test');
insert into conversations(id,business_id,instagram_participant_id,instagram_connection_id) values('00000000-0000-4000-8000-000000004141','00000000-0000-4000-8000-000000004101','participant','00000000-0000-4000-8000-000000004131');
insert into conversation_states(conversation_id,business_id) values('00000000-0000-4000-8000-000000004141','00000000-0000-4000-8000-000000004101');
insert into workflow_inbound_queue(business_id,connection_id,participant_id,external_id,payload) values('00000000-0000-4000-8000-000000004101','00000000-0000-4000-8000-000000004131','participant','message-1','{}'),('00000000-0000-4000-8000-000000004101','00000000-0000-4000-8000-000000004131','participant','message-2','{}');
do $$ declare a uuid:='00000000-0000-4000-8000-000000004101';b uuid:='00000000-0000-4000-8000-000000004102';c uuid:='00000000-0000-4000-8000-000000004141';job workflow_inbound_queue;next_job workflow_inbound_queue;s jsonb:='{"schemaVersion":2,"step_key":"collect_size","context":{"profile":{"phone":{"value":"+355691234567","type":"phone","source":"message","validated":true}}}}';
begin
 if exists(select 1 from claim_workflow_inbound(array[b])) then raise exception 'Foreign queue claimed';end if;
 select * into job from claim_workflow_inbound(array[a]);
 if job.external_id<>'message-1' then raise exception 'Messages reordered';end if;
 if exists(select 1 from claim_workflow_inbound(array[a])) then raise exception 'Concurrent conversation processing allowed';end if;
 begin perform prepare_workflow_reply(job.id,job.lease_token,c,99,s,null,'reply',null,false);raise exception 'Stale state accepted' using errcode='XX001';exception when raise_exception then if sqlerrm<>'stale_state' then raise;end if;end;
 if exists(select 1 from conversation_profiles where business_id=a) then raise exception 'Failed commit wrote memory';end if;
 perform prepare_workflow_reply(job.id,job.lease_token,c,0,s,null,'reply',null,false);
 if (select revision from conversation_states where conversation_id=c)<>1 or not exists(select 1 from conversation_profiles where business_id=a and participant_id='participant' and profile->'phone'->>'value'='+355691234567') then raise exception 'Atomic state/profile commit failed';end if;
 if begin_workflow_send(job.id,gen_random_uuid()) then raise exception 'Foreign lease used';end if;
 if not begin_workflow_send(job.id,job.lease_token) then raise exception 'Send not claimed';end if;
 if begin_workflow_send(job.id,job.lease_token) then raise exception 'Duplicate send allowed';end if;
 perform finish_workflow_send(job.id,job.lease_token,true,'out-1',null);
 if (select count(*) from messages where conversation_id=c and direction='outbound')<>1 then raise exception 'Outbound receipt missing';end if;
 select * into next_job from claim_workflow_inbound(array[a]);
 if next_job.external_id<>'message-2' then raise exception 'Next message not released';end if;
 update workflow_inbound_queue set leased_until=now()-interval '1 second' where id=next_job.id;
 select * into job from claim_workflow_inbound(array[a]);
 begin perform prepare_workflow_reply(job.id,next_job.lease_token,c,1,s,null,'reply',null,false);raise exception 'Expired worker committed' using errcode='XX001';exception when raise_exception then if sqlerrm<>'lease_lost' then raise;end if;end;
 perform prepare_workflow_reply(job.id,job.lease_token,c,1,s,null,'reply',null,false);
 perform begin_workflow_send(job.id,job.lease_token);
 update workflow_inbound_queue set leased_until=now()-interval '1 second' where id=job.id;
 perform claim_workflow_inbound(array[a]);
 if (select status from workflow_inbound_queue where id=job.id)<>'uncertain' or (select status from conversations where id=c)<>'paused' then raise exception 'Ambiguous delivery was not handed to staff';end if;
end $$;
rollback;
